// Filtro anti-output basura con contador para evitar loops infinitos
const textoAnalizar = $input.first().json.output?.respuesta || "";

const palabrasProhibidas = ["json", "temperatura", "comando", "ejecutado"];

const contienePalabra = palabrasProhibidas.some(p =>
  textoAnalizar.toLowerCase().includes(p.toLowerCase())
);

// Contador por ejecución (no por sessionId) — más simple y a prueba de balas
const staticData = $getWorkflowStaticData('node');
const execId = $execution.id;
const key = `reintentos_${execId}`;
const intentos = staticData[key] || 0;

let comandoSalida;
if (contienePalabra && intentos < 2) {
  staticData[key] = intentos + 1;
  comandoSalida = "repetir";
} else {
  delete staticData[key]; // limpiar al terminar
  comandoSalida = "sigue";
}

return { json: { comando: comandoSalida, intentos } };

